import type {
  AfterViewInit,
  ChangeDetectorRef,
  ElementRef,
  NgZone,
  OnChanges,
  OnDestroy,
} from "@angular/core";
import { UniversalPlayer } from "../../core/player.js";
import { sourceToken } from "../../core/source.js";
import { createInitialState } from "../../core/state.js";
import type {
  PlayerEvent,
  PlayerOptions,
  PlayerSourceInput,
  PlayerState,
} from "../../core/types.js";

/** Inputs forwarded from an Angular component. */
export type AngularUniversalPlayerInputs = Omit<
  PlayerOptions,
  "container" | "onStateChange" | "onEvent"
>;

/** Output callbacks forwarded to Angular outputs. */
export interface AngularUniversalPlayerOutputs {
  readonly ready?: (state: PlayerState) => void;
  readonly stateChange?: (state: PlayerState) => void;
  readonly error?: (error: Error) => void;
  readonly event?: (event: PlayerEvent) => void;
  readonly player?: (player: UniversalPlayer | null) => void;
}

/** Construction options for {@link AngularUniversalPlayer}. */
export interface AngularUniversalPlayerOptions {
  readonly elementRef: Pick<ElementRef<Element>, "nativeElement">;
  readonly ngZone?: Pick<NgZone, "run" | "runOutsideAngular">;
  readonly changeDetector?: Pick<ChangeDetectorRef, "markForCheck">;
  readonly inputs?: AngularUniversalPlayerInputs;
  readonly outputs?: AngularUniversalPlayerOutputs;
}

/**
 * Framework-neutral Angular controller.
 *
 * Angular libraries built with a generic bundler cannot emit partial
 * compilation metadata, so a precompiled `@Component` would not be AOT-safe.
 * Consumers therefore own the decorated standalone component and forward
 * lifecycle calls to this controller (see `examples/angular`).
 */
export class AngularUniversalPlayer implements AfterViewInit, OnChanges, OnDestroy {
  readonly #elementRef: Pick<ElementRef<Element>, "nativeElement">;
  readonly #ngZone: Pick<NgZone, "run" | "runOutsideAngular"> | null;
  readonly #changeDetector: Pick<ChangeDetectorRef, "markForCheck"> | null;
  readonly #listeners = new Set<(state: PlayerState) => void>();
  readonly #unsubscribes: Array<() => void> = [];

  #inputs: AngularUniversalPlayerInputs;
  #outputs: AngularUniversalPlayerOutputs;
  #player: UniversalPlayer | null = null;
  #state: PlayerState = createInitialState();
  #connected = false;
  #destroyed = false;
  #changeScheduled = false;
  #sourceTokenValue: string;
  #pending: Promise<void> = Promise.resolve();

  constructor(options: AngularUniversalPlayerOptions) {
    if (
      typeof options !== "object" ||
      options === null ||
      options.elementRef === undefined ||
      options.elementRef.nativeElement === undefined
    ) {
      throw new Error("AngularUniversalPlayer requires an ElementRef with a nativeElement.");
    }

    this.#elementRef = options.elementRef;
    this.#ngZone = options.ngZone ?? null;
    this.#changeDetector = options.changeDetector ?? null;
    this.#inputs = options.inputs ?? {};
    this.#outputs = options.outputs ?? {};
    this.#sourceTokenValue = sourceToken(this.#inputs.source);
  }

  /** Latest state snapshot. */
  get state(): PlayerState {
    return this.#state;
  }

  /** Live player, or null before connection/after destruction. */
  get player(): UniversalPlayer | null {
    return this.#player;
  }

  /** Whether `ngOnDestroy` has run. */
  get destroyed(): boolean {
    return this.#destroyed;
  }

  /** Replaces the outputs after construction. */
  setOutputs(outputs: AngularUniversalPlayerOutputs): void {
    this.#outputs = outputs;
  }

  /** Stores new inputs and applies them. */
  setInputs(inputs: AngularUniversalPlayerInputs): void {
    if (this.#destroyed) {
      throw new Error("Cannot set inputs: the Angular player has been destroyed.");
    }

    this.#inputs = inputs;
    this.#applyInputs();
  }

  /** Angular lifecycle hook. */
  ngOnChanges(): void {
    this.#applyInputs();
  }

  /** Angular lifecycle hook; creates the player once. */
  ngAfterViewInit(): void {
    if (this.#destroyed || this.#connected) {
      return;
    }

    this.#connected = true;
    this.#connect();
  }

  /** Angular lifecycle hook; terminal and idempotent. */
  ngOnDestroy(): void {
    if (this.#destroyed) {
      return;
    }

    this.#destroyed = true;

    for (const unsubscribe of this.#unsubscribes) {
      unsubscribe();
    }

    this.#unsubscribes.length = 0;
    const player = this.#player;
    this.#player = null;
    player?.destroy();
    this.#emit(() => this.#outputs.player?.(null));
    this.#listeners.clear();
  }

  /** Loads or replaces the source after connection. */
  load(source: PlayerSourceInput): Promise<void> {
    if (this.#destroyed) {
      return Promise.reject(new Error("Cannot load: the Angular player has been destroyed."));
    }

    if (this.#player === null) {
      return Promise.reject(new Error("Cannot load before ngAfterViewInit connects the player."));
    }

    return this.#player.load(source);
  }

  /** Starts playback. */
  play(): Promise<void> {
    return this.#player?.play() ?? Promise.resolve();
  }

  /** Pauses playback. */
  pause(): void {
    this.#player?.pause();
  }

  /** Seeks to an absolute time in seconds. */
  seek(time: number): void {
    this.#player?.seek(time);
  }

  /** Sets the volume in the 0–1 range. */
  setVolume(volume: number): void {
    this.#player?.setVolume(volume);
  }

  /** Mutes or unmutes playback. */
  setMuted(muted: boolean): void {
    this.#player?.setMuted(muted);
  }

  /** Sets the playback rate. */
  setPlaybackRate(rate: number): void {
    this.#player?.setPlaybackRate(rate);
  }

  /** Subscribes to state snapshots. */
  subscribe(listener: (state: PlayerState) => void): () => void {
    this.#listeners.add(listener);

    return () => {
      this.#listeners.delete(listener);
    };
  }

  /** Resolves after queued load work settles. */
  whenIdle(): Promise<void> {
    return this.#pending;
  }

  #connect(): void {
    const element = this.#elementRef.nativeElement;

    if (typeof HTMLElement === "undefined" || !(element instanceof HTMLElement)) {
      throw new Error("AngularUniversalPlayer requires an HTMLElement host.");
    }

    const { source: initialSource, ...rest } = this.#inputs;
    void initialSource;

    const instance = this.#runOutsideAngular(
      () =>
        new UniversalPlayer({
          ...rest,
          container: element,
          onEvent: (event) => this.#emit(() => this.#outputs.event?.(event)),
        }),
    );

    this.#player = instance;
    this.#state = instance.state;

    this.#unsubscribes.push(
      instance.on("statechange", (next) => {
        this.#publish(next);
      }),
      instance.on("timeupdate", (event) => {
        this.#state = {
          ...this.#state,
          currentTime: event.currentTime,
          duration: event.duration,
          buffered: event.buffered,
        };
        this.#scheduleChangeDetection();
      }),
      instance.on("loadedmetadata", () => {
        this.#emit(() => this.#outputs.ready?.(this.#state));
      }),
      instance.on("error", (event) => {
        this.#emit(() => this.#outputs.error?.(event.error));
      }),
      instance.on("statechange", (next) => {
        this.#emit(() => this.#outputs.stateChange?.(next));
      }),
    );

    this.#emit(() => this.#outputs.player?.(instance));
    this.#loadSource();
  }

  #loadSource(): void {
    const source = this.#inputs.source;

    if (source === undefined || this.#player === null) {
      return;
    }

    this.#pending = this.#player.load(source).catch(() => {
      // Failures are published through state and outputs.
    });
  }

  #applyInputs(): void {
    const nextToken = sourceToken(this.#inputs.source);
    const sourceChanged = nextToken !== this.#sourceTokenValue;
    this.#sourceTokenValue = nextToken;

    if (!this.#connected || this.#destroyed || this.#player === null) {
      return;
    }

    if (sourceChanged) {
      this.#loadSource();
      return;
    }

    const { volume, muted, playbackRate } = this.#inputs;

    if (volume !== undefined) {
      this.#player.setVolume(volume);
    }

    if (muted !== undefined) {
      this.#player.setMuted(muted);
    }

    if (playbackRate !== undefined) {
      this.#player.setPlaybackRate(playbackRate);
    }
  }

  #publish(next: PlayerState): void {
    this.#state = next;

    for (const listener of Array.from(this.#listeners)) {
      try {
        listener(next);
      } catch {
        // A listener must never break the player lifecycle.
      }
    }

    this.#scheduleChangeDetection();
  }

  #scheduleChangeDetection(): void {
    const changeDetector = this.#changeDetector;

    if (changeDetector === null || this.#destroyed || this.#changeScheduled) {
      return;
    }

    this.#changeScheduled = true;

    queueMicrotask(() => {
      this.#changeScheduled = false;

      if (this.#destroyed || this.#changeDetector === null) {
        return;
      }

      const notify = (): void => {
        this.#changeDetector?.markForCheck();
      };

      if (this.#ngZone === null) {
        notify();
      } else {
        this.#ngZone.run(notify);
      }
    });
  }

  #runOutsideAngular<T>(operation: () => T): T {
    return this.#ngZone === null ? operation() : this.#ngZone.runOutsideAngular(operation);
  }

  #emit(callback: () => void): void {
    try {
      callback();
    } catch {
      // Consumer callbacks are isolated like core event listeners.
    }
  }
}
